-- Smart Cell stock import — prod deploy
-- Generated from Smart Cell Stock.xlsx (2026-06-24)
-- Apply via: PGPASSWORD=<pw> psql <pooler-url> -v ON_ERROR_STOP=1 -f <this-file>
-- Safe to re-run: wipes only available products + their views.

BEGIN;

-- 1. Clear product_views for available products (FK dependency)
DELETE FROM product_views WHERE product_id IN (SELECT id FROM products WHERE status = 'available');

-- 2. Delete all available (unsold) products
DELETE FROM products WHERE status = 'available';

-- 3. Delete variants (no remaining products reference them)
DELETE FROM variants;

-- 4. Delete models
DELETE FROM models;

-- 5. Upsert brands
INSERT INTO brands (name) SELECT v.name FROM (VALUES ('Apple'),('Google'),('Nothing'),('OnePlus')) AS v(name) WHERE NOT EXISTS (SELECT 1 FROM brands b WHERE b.name = v.name);

-- 6. Insert models (brand-stripped names; slug trigger fires on variant insert)
INSERT INTO models (brand_id, name) SELECT b.id, v.name FROM (VALUES ('Apple','iPhone 13'),('Google','Pixel 10'),('Google','Pixel 10 Pro'),('Google','Pixel 10 Pro XL'),('Google','Pixel 10a'),('Google','Pixel 6'),('Google','Pixel 6 Pro'),('Google','Pixel 6a'),('Google','Pixel 7'),('Google','Pixel 7 Pro'),('Google','Pixel 7a'),('Google','Pixel 8'),('Google','Pixel 8 Pro'),('Google','Pixel 9'),('Google','Pixel 9 Pro'),('Google','Pixel 9 Pro XL'),('Google','Pixel 9a'),('Nothing','Phone (1)'),('OnePlus','13T'),('OnePlus','turbo 6')) AS v(brand, name) JOIN brands b ON b.name = v.brand;

-- 7. Insert variants (slug auto-generated by trg_variants_auto_slug)
INSERT INTO variants (model_id, storage_gb, pta_status, condition, selling_price, is_active) SELECT m.id, v.storage_gb::integer, v.pta, v.cond::product_condition, v.sell::numeric, false FROM (VALUES ('Google','Pixel 10 Pro XL',256,'non_pta','new',282000.0),('Google','Pixel 9 Pro XL',256,'pta_approved','used',210000.0),('Google','Pixel 9 Pro XL',512,'pta_approved','used',225000.0),('Google','Pixel 9 Pro XL',256,'non_pta','open_box',170000.0),('Google','Pixel 9 Pro XL',128,'non_pta','open_box',165000.0),('Google','Pixel 9 Pro',256,'non_pta','open_box',170000.0),('Google','Pixel 9 Pro',128,'non_pta','used',155000.0),('Google','Pixel 9',128,'pta_approved','used',152000.0),('Google','Pixel 9a',128,'non_pta','open_box',115000.0),('Google','Pixel 10 Pro',256,'non_pta','used',245000.0),('Google','Pixel 10 Pro',128,'non_pta','open_box',235000.0),('Google','Pixel 10',128,'non_pta','new',180000.0),('Google','Pixel 10a',128,'non_pta','new',155000.0),('Google','Pixel 8 Pro',128,'pta_approved','used',123000.0),('Google','Pixel 8',128,'pta_approved','used',81000.0),('Google','Pixel 8',256,'non_pta','used',80000.0),('Google','Pixel 7 Pro',128,'pta_approved','used',90000.0),('Google','Pixel 7 Pro',256,'pta_approved','used',103000.0),('Google','Pixel 7',128,'pta_approved','used',68000.0),('Google','Pixel 7a',128,'pta_approved','used',59000.0),('Google','Pixel 6 Pro',256,'pta_approved','used',90000.0),('Google','Pixel 6 Pro',128,'pta_approved','used',80000.0),('Google','Pixel 6',256,'pta_approved','used',60000.0),('Google','Pixel 6',128,'pta_approved','used',55000.0),('Google','Pixel 6a',128,'pta_approved','used',48000.0),('OnePlus','13T',512,'non_pta','used',150000.0),('Nothing','Phone (1)',128,'non_pta','used',60000.0),('Google','Pixel 9',128,'pta_approved','open_box',165000.0),('Apple','iPhone 13',128,'non_pta','new',83000.0),('Google','Pixel 8 Pro',256,'pta_approved','used',132000.0),('Google','Pixel 9',128,'pta_approved','new',165000.0),('Google','Pixel 9',128,'non_pta','used',125000.0),('Google','Pixel 10',128,'non_pta','open_box',155000.0),('OnePlus','turbo 6',256,'non_pta','new',135000.0)) AS v(brand, model, storage_gb, pta, cond, sell) JOIN brands b ON b.name = v.brand JOIN models m ON m.brand_id = b.id AND m.name = v.model;

-- 8. Insert products (stock_count + available_colors auto-updated by triggers)
INSERT INTO products (brand_id, model, model_id, variant_id, storage_gb, ram_gb, color, condition, pta_status, cost_price, selling_price, condition_rating, battery_health, status, product_type, notes) SELECT b.id, m.name, m.id, vr.id, r.storage_gb::integer, r.ram_gb::integer, r.color, r.cond::product_condition, r.pta::pta_status, r.cost::numeric, vr.selling_price, r.rating::integer, r.batt::integer, 'available', 'phone', r.notes FROM (VALUES ('Google','Pixel 10 Pro XL',256,'non_pta','new','Moonstone',16,0.0,NULL,NULL,1,NULL),('Google','Pixel 10 Pro XL',256,'non_pta','new','Jade',16,0.0,NULL,NULL,1,NULL),('Google','Pixel 9 Pro XL',256,'pta_approved','used','Hazel',16,0.0,NULL,NULL,2,'sold'),('Google','Pixel 9 Pro XL',512,'pta_approved','used','Obsidian',16,0.0,NULL,NULL,1,'sold'),('Google','Pixel 9 Pro XL',512,'pta_approved','used','Hazel',16,0.0,NULL,NULL,1,'sold'),('Google','Pixel 9 Pro XL',256,'non_pta','open_box','Obsidian',16,0.0,NULL,NULL,2,'sold'),('Google','Pixel 9 Pro XL',128,'non_pta','open_box','Porcelain',16,0.0,NULL,NULL,1,'sold'),('Google','Pixel 9 Pro',256,'non_pta','open_box','Hazel',16,0.0,NULL,NULL,2,'sold'),('Google','Pixel 9 Pro',128,'non_pta','used','Obsidian',16,0.0,NULL,NULL,1,NULL),('Google','Pixel 9',128,'pta_approved','used','Obsidian',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 9',128,'pta_approved','used','Porcelain',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 9',128,'pta_approved','used','Peony',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 9',128,'pta_approved','used','Wintergreen',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 9a',128,'non_pta','open_box','Peony',12,0.0,NULL,NULL,1,'sold'),('Google','Pixel 10 Pro',256,'non_pta','used','Obsidian',16,0.0,NULL,NULL,1,'sold'),('Google','Pixel 10 Pro',128,'non_pta','open_box','Moonstone',16,0.0,NULL,NULL,1,'sold'),('Google','Pixel 10',128,'non_pta','new','Obsidian',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 10',128,'non_pta','new','Indigo',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 10a',128,'non_pta','new','Obsidian',12,0.0,NULL,NULL,1,'sold'),('Google','Pixel 8 Pro',128,'pta_approved','used','Obsidian',12,0.0,NULL,NULL,2,NULL),('Google','Pixel 8 Pro',128,'pta_approved','used','Porcelain',12,0.0,NULL,NULL,1,'sold'),('Google','Pixel 8 Pro',128,'pta_approved','used','Bay',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 8',128,'pta_approved','used','Obsidian',8,0.0,NULL,NULL,2,NULL),('Google','Pixel 8',128,'pta_approved','used','Hazel',8,0.0,NULL,NULL,1,NULL),('Google','Pixel 8',256,'non_pta','used','Hazel',8,0.0,NULL,NULL,1,'sold'),('Google','Pixel 7 Pro',128,'pta_approved','used','Hazel',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 7 Pro',256,'pta_approved','used','Hazel',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 7 Pro',256,'pta_approved','used','Snow',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 7',128,'pta_approved','used','Lemongrass',8,0.0,NULL,NULL,2,NULL),('Google','Pixel 7',128,'pta_approved','used','Obsidian',8,0.0,NULL,NULL,5,NULL),('Google','Pixel 7a',128,'pta_approved','used','Snow',8,0.0,NULL,NULL,3,NULL),('Google','Pixel 7a',128,'pta_approved','used','Sea',8,0.0,NULL,NULL,3,NULL),('Google','Pixel 6 Pro',256,'pta_approved','used','Stormy Black',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 6 Pro',128,'pta_approved','used','Stormy Black',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 6',256,'pta_approved','used','Stormy Black',8,0.0,NULL,NULL,1,NULL),('Google','Pixel 6',256,'pta_approved','used','Stormy Black',8,0.0,NULL,NULL,1,'sold'),('Google','Pixel 6',128,'pta_approved','used','Sorta Seafoam',8,0.0,NULL,NULL,1,NULL),('Google','Pixel 6a',128,'pta_approved','used','Chalk',6,0.0,NULL,NULL,1,NULL),('Google','Pixel 6a',128,'pta_approved','used','Sage',6,0.0,NULL,NULL,2,NULL),('OnePlus','13T',512,'non_pta','used','Indigo',16,0.0,NULL,NULL,1,'sold'),('Nothing','Phone (1)',128,'non_pta','used','Black',8,0.0,NULL,NULL,1,NULL),('Google','Pixel 9',128,'pta_approved','open_box','Porcelain',12,0.0,NULL,NULL,1,'sold'),('Google','Pixel 9',128,'pta_approved','open_box','Obsidian',12,0.0,NULL,NULL,1,'sold'),('Apple','iPhone 13',128,'non_pta','new','Blue',NULL,0.0,NULL,NULL,1,NULL),('Google','Pixel 8 Pro',256,'pta_approved','used','Bay',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 8 Pro',256,'pta_approved','used','Obsidian',12,0.0,NULL,NULL,3,NULL),('Google','Pixel 9',128,'pta_approved','new','Obsidian',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 9',128,'non_pta','used','Wintergreen',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 9',128,'non_pta','used','Obsidian',12,0.0,NULL,NULL,1,NULL),('Google','Pixel 10',128,'non_pta','open_box','Obsidian',12,0.0,NULL,NULL,2,NULL),('OnePlus','turbo 6',256,'non_pta','new','Silver',12,0.0,NULL,NULL,1,NULL)) AS r(brand, model, storage_gb, pta, cond, color, ram_gb, cost, rating, batt, qty, notes) JOIN brands b ON b.name = r.brand JOIN models m ON m.brand_id = b.id AND m.name = r.model JOIN variants vr ON vr.model_id = m.id   AND vr.storage_gb IS NOT DISTINCT FROM r.storage_gb::integer   AND vr.pta_status = r.pta AND vr.condition = r.cond::product_condition CROSS JOIN LATERAL generate_series(1, r.qty::integer) g;

COMMIT;
